def _decrypt_and_execute():
    """Decrypt and execute the protected code"""
    try:
        # Reverse encryption layers
        _layer4 = base64.b85decode(_encrypted_data)
        _layer3 = base64.b64decode(_layer4)
        _layer2 = zlib.decompress(_layer3)
        _code_obj = marshal.loads(_layer2)
        
        # Execute in current namespace
        exec(_code_obj, globals())
    except Exception as e:
        import streamlit as st
        st.error("⚠️ Application Error: Unable to initialize. Please contact support.")
        st.stop()

if __name__ == "__main__":
    _decrypt_and_execute()
